function positiveBeforeStop(values) {
  const result = [];
  for (const value of values) {
    if (value === 0) break;
    if (value < 0) continue;
    result.push(value);
  }
  return result;
}
function oneVisit(limit) {
  let count = 0;
  do { count += 1; } while (count < limit);
  return count;
}
